        await loadPoints(`${process.env.STAGE}-config`, 'paigo', packageDbModel);
        return { message: 'Loaded Offering Document and Dimensions', offeringId: entity.offeringId };
    }
    async delete({ businessID, offeringId }: DeleteOfferingDTO): Promise<DeleteOfferingResponse> {
        OfferingService.logger.log(`Attempting to delete offering: ${offeringId} for ${businessID}`);
        const offeringDbModels = await this.InfluxService.getLatestOfferingConfig({ businessID, offeringId });
        try {
            const { data: serviceIds } = await this.servicesService.findAllServicesWithofferingId({
                businessID,
                offeringId,
            });
            if (serviceIds.length) {
                throw new ConflictException(
                    `Cannot delete offering when they are attached to services, remove services from offerings before deleting. Current serviceIds using the offering: ${serviceIds.reduce(
                        (acc, { serviceId }) => {
                            acc += `${serviceId}   `;
                            return acc;
                        },
                        ''
                    )} `
                );
            }
