                        (acc, { customerId }) => {
                            acc += `${customerId}   `;
                            return acc;
                        },
                        ''
                    )} `
                );
            }
        } catch (error) {
            if (error instanceof NotFoundException) {
            } else {
                throw error;
            }
        }
        if (offeringDbModels.length) {
            const { loadPoints } = this.InfluxService;
